(()=>{const L=Lab;
 const picker=()=>`<label class="origin-picker">排查哪项任务<select data-origin-select>${L.visible().length?L.visible().map(t=>`<option value="${t.id}" ${t.id===L.state.origin?'selected':''}>${t.code} ${L.esc(t.title)}</option>`).join(''):'<option disabled>此筛选下没有任务，当前路径保留</option>'}</select></label>`;
 L.modes.C={name:'逐层栏',purpose:'保留前一层选择，在相邻一栏继续查看前置。',headline:'逐层追踪前置',render:()=>{
  const path=[...L.state.history,L.state.focus];return `${picker()}<div class="columns" aria-label="逐层前置路径">${path.map((id,i)=>{const t=L.task(id);return `<section class="drill-column"><span class="eyebrow">第 ${i+1} 层 / ${i===0?'原任务':'前置对象'}</span><h2>${L.esc(t.title)}</h2>${L.badge(t)}<p class="quiet">${L.open(t).length} 项前置未完成</p>${t.reason?`<p class="reason">${L.esc(t.reason)}</p>`:''}${L.dependencies(t)}<div class="column-output"><small>预期产出</small><p>${L.esc(t.output)}</p></div></section>`;}).join('')}<section class="drill-guide"><span class="eyebrow">下一层</span><h3>${L.deps().length?'选择一项前置继续。':'已经到达这条路径的末端。'}</h3><p>前一层的选择保留在相邻栏。没有前置不代表人工阻塞已解除。</p></section></div>`;
 }};
 L.modes.D={name:'阻塞档案',purpose:'围绕“为什么不能继续”组织原因、对象与产出依据。',headline:'先把原因看清',render:()=>{
  const t=L.task(L.state.focus),all=L.deps(t),shown=all.filter(d=>!L.state.hideDone||d.status!=='已完成');
  return `<div class="dossier"><div class="dossier-main"><p class="eyebrow">// INVESTIGATION / ${t.code}</p><h2>${L.esc(t.title)}</h2><p class="dossier-lead">${t.reason?'这项工作被人工标记为阻塞。':L.open(t).length?'执行状态尚未变化，但前置条件还未全部满足。':'没有未完成的前置条件；是否推进仍需核对任务本身。'}</p>${t.reason?`<div class="reason">${L.esc(t.reason)}</div>`:''}<div class="cause-head"><h3>逐项核对原因</h3><span>显示 ${shown.length} / 全部 ${all.length}</span></div>${shown.map((d,i)=>`<section class="cause"><span class="cause-no">${i+1}</span><div><p class="code">${d.code} / ${L.project(d.project)}</p><h3>${L.esc(d.title)}</h3><p>${d.reason?L.esc(d.reason):d.missing?'引用对象不可用，不能判为已完成。':L.open(d).length?`还需要 ${L.open(d).length} 项前置完成。`:d.status==='已完成'?'此项已完成，保留为核验依据。':'没有下级前置，尚需完成其自身工作。'}</p></div><div>${L.badge(d)}<button data-act="focus" data-id="${d.id}" ${d.missing?'disabled':''}>${d.missing?'无法查看':'查看原因 →'}</button></div></section>`).join('')}${!shown.length?'<p class="quiet">当前没有可显示的前置原因。</p>':''}<section class="expected"><h3>这项工作应留下什么</h3><p>${L.esc(t.output)}</p><small>这是预期产出，不代表文件已经存在或工作已经完成。</small></section></div><aside class="dossier-side"><span class="eyebrow">判断依据</span><p>执行状态</p>${L.badge(t)}<p>前置满足情况</p><strong>${all.length-L.open(t).length} / ${all.length}</strong><p>为哪个原任务检查</p><b>${L.esc(L.task(L.state.origin).title)}</b><hr><p>继续追查不会修改状态。<br>返回时保留范围与查询。</p></aside></div>`;
 }};
})();
